/**
 * WorkspaceContext — shared application state for the active project/snapshot.
 *
 * This is the deliberate integration surface for all feature modules.
 * Feature components access project identity, snapshot, selected entity,
 * source range, and navigation callbacks through this context.
 *
 * Integration slots read from this context to receive the selected file/entity.
 * They must not create parallel project or snapshot state.
 *
 * Public interface (stable — do not change without updating integration guide):
 *   useWorkspace()        — consume the context
 *   WorkspaceProvider     — wrap the workspace routes
 *   WorkspaceState        — the full state shape
 */

import {
  createContext,
  useCallback,
  useContext,
  useState,
  type ReactNode,
} from 'react'

import type { FileRecord, Graph, Snapshot } from '../types/v1'

// ── Selected entity ────────────────────────────────────────────────────────

export interface SelectedEntity {
  /** Entity ID in the graph (stable within a snapshot) */
  entityId: string
  /** Kind: file | directory | virtual_group */
  kind: string
  /** Relative path in the repository */
  path: string
  /** FileRecord ID if this is a file entity */
  fileId?: string
  /** Source line range requested (1-based inclusive) */
  lineRange?: { start: number; end: number }
}

// ── View state ─────────────────────────────────────────────────────────────

export interface ViewState {
  /** Which view is focused: 'overview' | 'map' | 'source' */
  focusedView: 'overview' | 'map' | 'source'
  mapCamera: { x: number; y: number; scale: number }
}

const DEFAULT_VIEW_STATE: ViewState = {
  focusedView: 'overview',
  mapCamera: { x: 0, y: 0, scale: 1 },
}

// ── Workspace state ────────────────────────────────────────────────────────

export interface WorkspaceState {
  /** Currently loaded project ID */
  projectId: string | null
  /** Currently loaded project name */
  projectName: string | null
  /** Active snapshot (the selected revision) */
  snapshot: Snapshot | null
  /** All snapshots available for this project */
  snapshots: Snapshot[]
  /** Currently selected entity in the tree/map/source */
  selectedEntity: SelectedEntity | null
  /** Cached structural graph for the active snapshot */
  graph: Graph | null
  /** All file records for the active snapshot */
  files: FileRecord[]
  /** View state (camera, focus) */
  viewState: ViewState
  /** Whether the workspace is currently loading */
  loading: boolean
  /** Error message if loading failed */
  error: string | null
}

// ── Workspace actions ──────────────────────────────────────────────────────

export interface WorkspaceActions {
  /** Load a project + snapshot into the workspace */
  loadWorkspace(projectId: string, snapshotId: string | null): Promise<void>
  /** Select an entity (syncs tree, map, source panel) */
  selectEntity(entity: SelectedEntity | null): void
  /** Update the source line range for the selected entity */
  setLineRange(range: { start: number; end: number } | undefined): void
  /** Update the map camera state */
  setMapCamera(camera: ViewState['mapCamera']): void
  /** Set the focused view */
  setFocusedView(view: ViewState['focusedView']): void
  /** Update the graph (called after fetch) */
  setGraph(graph: Graph | null): void
  /** Update the file list */
  setFiles(files: FileRecord[]): void
  /** Set snapshot list */
  setSnapshots(snapshots: Snapshot[]): void
  /** Set active snapshot */
  setSnapshot(snapshot: Snapshot | null): void
  /** Clear error */
  clearError(): void
}

export type WorkspaceContextValue = WorkspaceState & WorkspaceActions

// ── Context ────────────────────────────────────────────────────────────────

const WorkspaceContext = createContext<WorkspaceContextValue | null>(null)

export function WorkspaceProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<WorkspaceState>({
    projectId: null,
    projectName: null,
    snapshot: null,
    snapshots: [],
    selectedEntity: null,
    graph: null,
    files: [],
    viewState: DEFAULT_VIEW_STATE,
    loading: false,
    error: null,
  })

  const loadWorkspace = useCallback(async (projectId: string, snapshotId: string | null) => {
    setState(s => ({ ...s, loading: true, error: null }))
    try {
      const { listSnapshots } = await import('../services/v1/api')
      const snapshots = await listSnapshots(projectId)

      const snapshot =
        (snapshotId ? snapshots.find(s => s.id === snapshotId) : snapshots[snapshots.length - 1]) ?? null

      // Derive project name from snapshot source
      const projectName = snapshot
        ? (snapshot.source.repo
            ? `${snapshot.source.owner ?? ''}/${snapshot.source.repo}`
            : snapshot.id.slice(0, 8))
        : projectId.slice(0, 8)

      setState(s => ({
        ...s,
        projectId,
        projectName,
        snapshot,
        snapshots,
        loading: false,
        error: null,
        selectedEntity: null,
        graph: null,
        files: [],
      }))
    } catch (e) {
      const message = e instanceof Error ? e.message : 'Failed to load workspace.'
      setState(s => ({ ...s, loading: false, error: message }))
    }
  }, [])

  const selectEntity = useCallback((entity: SelectedEntity | null) => {
    setState(s => ({ ...s, selectedEntity: entity }))
  }, [])

  const setLineRange = useCallback((range: { start: number; end: number } | undefined) => {
    setState(s => ({
      ...s,
      selectedEntity: s.selectedEntity
        ? { ...s.selectedEntity, lineRange: range }
        : null,
    }))
  }, [])

  const setMapCamera = useCallback((camera: ViewState['mapCamera']) => {
    setState(s => ({ ...s, viewState: { ...s.viewState, mapCamera: camera } }))
  }, [])

  const setFocusedView = useCallback((view: ViewState['focusedView']) => {
    setState(s => ({ ...s, viewState: { ...s.viewState, focusedView: view } }))
  }, [])

  const setGraph = useCallback((graph: Graph | null) => {
    setState(s => ({ ...s, graph }))
  }, [])

  const setFiles = useCallback((files: FileRecord[]) => {
    setState(s => ({ ...s, files }))
  }, [])

  const setSnapshots = useCallback((snapshots: Snapshot[]) => {
    setState(s => ({ ...s, snapshots }))
  }, [])

  const setSnapshot = useCallback((snapshot: Snapshot | null) => {
    setState(s => ({ ...s, snapshot }))
  }, [])

  const clearError = useCallback(() => {
    setState(s => ({ ...s, error: null }))
  }, [])

  const value: WorkspaceContextValue = {
    ...state,
    loadWorkspace,
    selectEntity,
    setLineRange,
    setMapCamera,
    setFocusedView,
    setGraph,
    setFiles,
    setSnapshots,
    setSnapshot,
    clearError,
  }

  return (
    <WorkspaceContext.Provider value={value}>
      {children}
    </WorkspaceContext.Provider>
  )
}

/** Consume the workspace context. Throws if used outside WorkspaceProvider. */
export function useWorkspace(): WorkspaceContextValue {
  const ctx = useContext(WorkspaceContext)
  if (!ctx) {
    throw new Error('useWorkspace must be used within a WorkspaceProvider')
  }
  return ctx
}

